package app.flare.auto;
import android.bluetooth.*;import android.content.*;import android.graphics.*;import android.net.*;import android.telephony.TelephonyManager;import android.view.View;

final class DeviceStatus extends View {
 final boolean bluetooth;final Paint paint=new Paint(3);final Path glyph=new Path(),slash=new Path();final int primary,secondary,background;final BluetoothAdapter adapter;final ConnectivityManager connectivity;boolean registered,receiverRegistered;int state=-1;
 final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){refresh();}};
 final ConnectivityManager.NetworkCallback network=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network n){post(()->refresh());}@Override public void onLost(Network n){post(()->refresh());}@Override public void onCapabilitiesChanged(Network n,NetworkCapabilities cap){post(()->refresh());}};
 DeviceStatus(Context c,boolean bt){super(c);bluetooth=bt;ThemeTokens t=ThemeTokens.get(c);primary=t.textPrimary;secondary=t.textSecondary;background=t.background;adapter=BluetoothAdapter.getDefaultAdapter();connectivity=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.7f);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);if(bt){glyph.moveTo(12,2);glyph.lineTo(12,22);glyph.lineTo(18,17);glyph.lineTo(6,7);glyph.moveTo(6,17);glyph.lineTo(18,7);glyph.lineTo(12,2);}else{for(int n=0;n<4;n++){float x=3+n*5;glyph.moveTo(x,21);glyph.lineTo(x,18-n*4);}}slash.moveTo(4,20);slash.lineTo(20,4);}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();IntentFilter f=new IntentFilter();if(bluetooth){f.addAction(BluetoothAdapter.ACTION_STATE_CHANGED);f.addAction(BluetoothAdapter.ACTION_CONNECTION_STATE_CHANGED);f.addAction(BluetoothDevice.ACTION_ACL_CONNECTED);f.addAction(BluetoothDevice.ACTION_ACL_DISCONNECTED);}else f.addAction("android.intent.action.SIM_STATE_CHANGED");getContext().registerReceiver(receiver,f);receiverRegistered=true;if(!bluetooth)try{connectivity.registerNetworkCallback(new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_CELLULAR).build(),network);registered=true;}catch(RuntimeException ignored){}refresh();}
 @Override protected void onDetachedFromWindow(){if(registered){connectivity.unregisterNetworkCallback(network);registered=false;}if(receiverRegistered){getContext().unregisterReceiver(receiver);receiverRegistered=false;}super.onDetachedFromWindow();}
 void refresh(){int value=0;if(bluetooth){try{if(adapter!=null&&adapter.isEnabled()){value=1;if(adapter.getProfileConnectionState(BluetoothProfile.A2DP)==BluetoothProfile.STATE_CONNECTED||adapter.getProfileConnectionState(BluetoothProfile.HEADSET)==BluetoothProfile.STATE_CONNECTED)value=2;}}catch(SecurityException ignored){}}else{try{TelephonyManager t=(TelephonyManager)getContext().getSystemService(Context.TELEPHONY_SERVICE);if(t!=null&&t.getSimState()==TelephonyManager.SIM_STATE_READY)value=2;for(Network n:connectivity.getAllNetworks()){NetworkCapabilities cap=connectivity.getNetworkCapabilities(n);if(cap!=null&&cap.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR))value=2;}}catch(RuntimeException ignored){}setVisibility(value==0?GONE:VISIBLE);}if(value!=state){state=value;setContentDescription(bluetooth?(value==0?"Bluetooth off":value==1?"Bluetooth on":"Bluetooth connected"):"Mobile network available");invalidate();}}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();float size=Math.min(getWidth(),getHeight());c.translate((getWidth()-size)/2,(getHeight()-size)/2);c.scale(size/24,size/24);c.translate(2,2);c.scale(20f/24,20f/24);if(!bluetooth)c.translate(1.5f,0);paint.setStrokeWidth(1.7f);paint.setColor(state==2?primary:secondary);c.drawPath(glyph,paint);if(bluetooth&&state==0){paint.setColor(background);paint.setStrokeWidth(4);c.drawPath(slash,paint);paint.setColor(secondary);paint.setStrokeWidth(1.5f);c.drawPath(slash,paint);}c.restore();}
}
